describe('Product Search Functionality', () => {
    beforeEach(() => {
        cy.visit('/'); // Visit the homepage or search page
    });

    it('should display search results when a valid keyword is entered', () => {
        cy.get('input[name="search"]').type('laptop'); // Type a valid keyword
        cy.get('button[type="submit"]').click(); // Click the search button
        cy.get('.search-results').should('be.visible'); // Check if search results are visible
        cy.get('.search-results').children().should('have.length.greaterThan', 0); // Ensure there are results
        cy.get('.search-results').contains('laptop'); // Verify that results contain the keyword
    });

    it('should show no results message when an invalid keyword is entered', () => {
        cy.get('input[name="search"]').type('xyzabc'); // Type an invalid keyword
        cy.get('button[type="submit"]').click(); // Click the search button
        cy.get('.no-results').should('be.visible'); // Check if no results message is visible
        cy.get('.no-results').contains('No products found'); // Verify the no results message
    });
});
